"""Build and load the local FAISS index of ``references/`` files.

The file-based knowledge tier: reference markdown under the agent root
(``references/``, ``source="global"``) and per-skill (``skills/<id>/references/``,
``source=<skill_id>``) is indexed into a local FAISS store at ``rasa train`` and
loaded at runtime — on the same ``core/information_retrieval`` stack the external
knowledge stores use. Embeddings come from a ``model_groups`` id named by
``agent.yml`` ``knowledge_answering.embeddings``. An empty name uses the built-in
OpenAI embedder. Files are split at index time with
``knowledge_answering.chunking`` (character size and overlap).
"""

from __future__ import annotations

from pathlib import Path
from typing import TYPE_CHECKING, Any, Optional

import structlog

from rasa.core.information_retrieval.faiss import EMBEDDING_BATCH_SIZE, FAISS_Store
from rasa.core.information_retrieval.ingestion.text_splitter import (
    RecursiveCharacterTextSplitter,
)
from rasa.core.policies.enterprise_search_policy_config import DEFAULT_EMBEDDINGS_CONFIG
from rasa.exceptions import ValidationError
from rasa.mantle.config.agent_spec import (
    REFERENCES_EMBEDDINGS_DEFAULT_HINT,
    AgentSpec,
    ReferenceChunkingConfig,
    agent_spec_from_config,
)
from rasa.mantle.config.model_group_lookup import resolve_named_model_group
from rasa.mantle.model_archive.bootstrap import resolve_integration_model_groups
from rasa.shared.exceptions import InvalidConfigException
from rasa.shared.project_structure import (
    MANTLE_AGENT_FILE,
    MANTLE_INTEGRATIONS_FILE,
    MANTLE_REFERENCES_DIR,
    MANTLE_SKILLS_DIR,
)
from rasa.shared.providers.model_group_validation import (
    validate_model_group_credentials,
)
from rasa.shared.utils.llm import embedder_factory
from rasa.shared.utils.yaml import read_config_file

if TYPE_CHECKING:
    from rasa.core.information_retrieval.models import Document
    from rasa.shared.providers.embedding.embedding_client import EmbeddingClient

structlogger = structlog.get_logger()

# Subdirectory of the snapshot that holds the packaged FAISS index.
V2_REFERENCES_INDEX_DIR = "references_index"


def resolve_references_embeddings_config(
    agent: AgentSpec, model_groups: list[dict[str, Any]]
) -> Optional[dict[str, Any]]:
    """Resolve ``knowledge_answering.embeddings`` to a validated model group.

    An omitted or blank name returns ``None``: ``embedder_factory`` then builds
    the built-in OpenAI embedder from ``DEFAULT_EMBEDDINGS_CONFIG``, so no lookup
    runs. A set name must match one group in *model_groups*; the match goes
    through the shared lookup so references and the orchestrator fail the
    same way on an unknown id, and credentials are checked on the match.

    Args:
        agent: Parsed ``agent.yml``.
        model_groups: ``model_groups`` definitions already loaded by the caller.

    Returns:
        The matching group definition, or ``None`` for the built-in embedder.

    Raises:
        InvalidConfigException: When a set name matches no group (or the group
            list is empty), or the matched group has invalid credentials. The
            message names the id and never includes a credential value.
    """
    group_id = agent.knowledge_answering.embeddings.strip()
    if not group_id:
        return None

    try:
        embeddings_config = resolve_named_model_group(
            group_id, model_groups, part="knowledge_answering"
        )
    except InvalidConfigException as error:
        raise InvalidConfigException(
            f"{error} Model group '{group_id}' must exist in "
            f"'{MANTLE_INTEGRATIONS_FILE}'. {REFERENCES_EMBEDDINGS_DEFAULT_HINT}"
        ) from error

    try:
        validate_model_group_credentials([embeddings_config])
    except ValidationError as error:
        raise InvalidConfigException(
            f"The knowledge_answering embeddings model group '{group_id}' in "
            f"'{MANTLE_INTEGRATIONS_FILE}' has invalid credentials: "
            f"{error.info or error}"
        ) from error
    return embeddings_config


def build_references_embedder(
    agent: AgentSpec, model_groups: list[dict[str, Any]]
) -> "EmbeddingClient":
    """Resolve the references embeddings model group into an embedding client.

    See :func:`resolve_references_embeddings_config` for how the name is
    resolved. A resolved group is still handed to ``embedder_factory`` with
    ``DEFAULT_EMBEDDINGS_CONFIG`` as the merge base; ``FAISS_Store`` consumes
    the returned client directly.
    """
    embeddings_config = resolve_references_embeddings_config(agent, model_groups)
    return embedder_factory(embeddings_config, DEFAULT_EMBEDDINGS_CONFIG)


def _load_reference_dir(references_dir: Path, scope: str) -> list["Document"]:
    """Load ``*.md`` documents from one references folder, tagged with *scope*.

    An absolute ``source`` would point inside the temporary snapshot directory
    that no longer exists on the serving host, so each document's ``source`` is
    the path relative to *references_dir* (e.g. ``policy.md`` or
    ``billing/fees.md``) to keep citations portable. A ``scope`` tag
    (``"global"`` or the skill id) records which knowledge tier it came from.
    """
    if not references_dir.is_dir():
        return []

    from rasa.core.information_retrieval.models import Document

    documents: list[Document] = []
    for file_path in sorted(references_dir.glob("**/*.md")):
        if not file_path.is_file():
            continue
        text = file_path.read_text(encoding="utf-8")
        # Drop empty/whitespace-only files: they yield zero chunks at split time,
        # and a build where *every* reference is empty would otherwise crash FAISS
        # with a confusing "No documents found" error instead of skipping cleanly.
        if not text.strip():
            continue
        documents.append(
            Document(
                text=text,
                metadata={
                    "source": str(file_path.relative_to(references_dir)),
                    "scope": scope,
                },
            )
        )
    return documents


def _load_reference_documents(snapshot_root: Path) -> list["Document"]:
    """Collect reference docs from the global folder and every skill folder.

    Global references live at ``<snapshot>/references/`` (``scope="global"``);
    per-skill references at ``<snapshot>/skills/<id>/references/``
    (``scope=<skill_id>``). ``_``-prefixed skill dirs are skipped, mirroring the
    skill loader.
    """
    documents = _load_reference_dir(
        snapshot_root / MANTLE_REFERENCES_DIR, scope="global"
    )

    skills_root = snapshot_root / MANTLE_SKILLS_DIR
    if skills_root.is_dir():
        for skill_dir in sorted(skills_root.iterdir()):
            if not skill_dir.is_dir() or skill_dir.name.startswith("_"):
                continue
            documents += _load_reference_dir(
                skill_dir / MANTLE_REFERENCES_DIR, scope=skill_dir.name
            )
    return documents


def _chunk_reference_documents(
    documents: list["Document"],
    chunking: ReferenceChunkingConfig,
) -> list["Document"]:
    """Split loaded reference files into embeddable chunks.

    Uses the same recursive character splitter as CALM FAISS. Metadata
    (``source``, ``scope``) is copied onto every chunk. Whitespace-only chunks
    are dropped so a split that yields nothing is treated like empty files.
    """
    splitter = RecursiveCharacterTextSplitter(
        chunk_size=chunking.chunk_size,
        chunk_overlap=chunking.chunk_overlap,
        length_function=len,
    )
    return [
        chunk for chunk in splitter.split_documents(documents) if chunk.text.strip()
    ]


def _load_agent_from_snapshot(snapshot_root: Path) -> AgentSpec:
    """Parse the packaged ``agent.yml`` into an :class:`AgentSpec`.

    Reads with ``expand_env_vars=False`` to match the runtime bootstrap read
    (``bootstrap._read_agent_yaml_from_archive``). If train expanded ``${VAR}``
    interpolation (e.g. in ``knowledge_answering.embeddings``) while load kept
    it literal,
    the FAISS index would be built against a different model group than load
    resolves, and the knowledge index would silently drop at runtime.
    """
    agent_path = snapshot_root / MANTLE_AGENT_FILE
    config_data = (
        read_config_file(str(agent_path), expand_env_vars=False)
        if agent_path.is_file()
        else None
    )
    return agent_spec_from_config(config_data)


def build_references_index(snapshot_root: Path, project_root: Path) -> None:
    """Build the local FAISS index from packaged references and write it in-snapshot.

    Called during ``package_model_archive`` after the snapshot is populated.
    Resolves the embeddings first (``model_groups`` id from the
    project ``integrations.yml``), so a set ``knowledge_answering.embeddings`` that
    matches no group fails train even when there is nothing to index. Then reads
    reference ``.md`` files from the snapshot, splits them with ``agent.yml``
    ``knowledge_answering.chunking``, and persists a FAISS index to
    ``<snapshot>/references_index/``. Skips silently when the project ships no
    reference files (or none remain after chunking); the embedding client is
    only built when there is something to embed.
    """
    agent = _load_agent_from_snapshot(snapshot_root)
    model_groups = resolve_integration_model_groups(project_root)
    embeddings_config = resolve_references_embeddings_config(agent, model_groups)

    documents = _load_reference_documents(snapshot_root)
    if not documents:
        structlogger.debug("mantle.packaging.references_index.no_references")
        return

    chunking = agent.knowledge_answering.chunking
    chunks = _chunk_reference_documents(documents, chunking)
    if not chunks:
        structlogger.debug("mantle.packaging.references_index.no_chunks")
        return

    embedder = embedder_factory(embeddings_config, DEFAULT_EMBEDDINGS_CONFIG)

    index_path = snapshot_root / V2_REFERENCES_INDEX_DIR
    store = FAISS_Store(embeddings=embedder)
    for start in range(0, len(chunks), EMBEDDING_BATCH_SIZE):
        batch = chunks[start : start + EMBEDDING_BATCH_SIZE]
        store.add_texts(
            [chunk.text for chunk in batch],
            metadatas=[chunk.metadata for chunk in batch],
        )
    store.save(index_path / "documents_faiss")
    structlogger.info(
        "mantle.packaging.references_index.wrote",
        index_path=str(index_path),
        document_count=len(documents),
        chunk_count=len(chunks),
        chunk_size=chunking.chunk_size,
        chunk_overlap=chunking.chunk_overlap,
    )


def load_references_index(
    snapshot_root: Path,
    agent: AgentSpec,
    model_groups: list[dict[str, Any]],
) -> Optional[FAISS_Store]:
    """Load the packaged references FAISS index, or ``None`` when absent.

    Resolves the same embeddings the index was built with (so query embeddings
    match), then loads the persisted index. ``knowledge_answering.top_k`` sets
    how many chunks a later search of the local index returns; omitting it
    keeps four. That count is not part of the saved index. Returns ``None``
    when the project shipped no references (no index was packaged), when the
    embeddings config can no longer be resolved, or when the persisted index
    fails to load (corrupt or
    unreadable store): references are an optional add-on, so any such problem
    degrades to "no knowledge index" rather than failing model load.
    """
    index_dir = snapshot_root / V2_REFERENCES_INDEX_DIR
    if not (index_dir / "documents_faiss").is_dir():
        return None

    try:
        embedder = build_references_embedder(agent, model_groups)
    except Exception as error:
        # References are an optional add-on: any failure to resolve/construct the
        # embedder must degrade to "no knowledge index", never abort model load.
        # Besides InvalidConfigException (unresolvable model group), embedder
        # construction can raise on a provider whose SDK/plugin is present at
        # train time but missing on the serving host, or a model config lacking a
        # provider — those must not crash boot either.
        structlogger.warning(
            "mantle.references_index.load.embeddings_unresolved",
            embeddings=agent.knowledge_answering.embeddings,
            error=str(error),
        )
        return None

    try:
        return FAISS_Store(
            embeddings=embedder,
            index_path=str(index_dir),
            docs_folder=None,
            create_index=False,
            search_k=agent.knowledge_answering.top_k,
        )
    except Exception as error:
        # A packaged-but-unreadable index must not block model load; degrade to
        # "no knowledge index" (the message path stays up, just without search).
        structlogger.warning(
            "mantle.references_index.load.failed",
            index_dir=str(index_dir),
            error=str(error),
        )
        return None
